presets.css:
/* 长夜＆机械之心 『作者：长夜何其多』 禁二改二传商用 */

/* ========== A. 主题变量 ========== */
.chat-thread {
  --dress-chat-bg-overlay: transparent;
  --dress-header-title-color: #ffffff;
  --dress-header-title-size: 14px;
  --dress-header-title-weight: 100;
  --dress-header-icon-color: #ffffff;

  --dress-bubble-me-bg: #ffffff !important;
  --dress-bubble-me-bg-gradient: linear-gradient(#ffffff, #ffffff) !important; 
  --dress-bubble-me-fg: #000000 !important;
  --dress-bubble-me-border: 1px solid rgba(0, 0, 0, 0.2);
  --dress-bubble-me-radius: 0px !important; 

  --dress-bubble-them-bg: #000000 !important;
  --dress-bubble-them-bg-gradient: linear-gradient(#000000, #000000) !important;
  --dress-bubble-them-fg: #ffffff !important;
  --dress-bubble-them-border: 1px solid rgba(255, 255, 255, 0.2) !important;
  --dress-bubble-them-radius: 0px !important; 

  --dress-timestamp-color: var(--soft);

  background-color: #000000 !important;
  background-image: none !important;
  z-index: 0 !important;
}

html[data-theme="dark"] .chat-thread {
  --dress-header-title-color: #ffffff;
  --dress-header-icon-color: #ffffff;
  --dress-bubble-me-bg: #ffffff !important;
  --dress-bubble-me-bg-gradient: linear-gradient(#ffffff, #ffffff) !important;
  --dress-bubble-them-bg: #000000 !important;
  --dress-bubble-them-bg-gradient: linear-gradient(#000000, #000000) !important;
  background-color: #000000 !important;
}

.chat-thread .chat-list,
.chat-thread .chat-messages,
.chat-thread .chat-scroll,
.chat-thread [class*="message-list"],
.chat-thread [class*="msg-list"],
.chat-thread .chat-body,
.chat-thread .chat-content {
  background-color: #000000 !important;
  background-image: none !important;
  z-index: 0 !important;
}

/* ========== B. 顶栏 ========== */
.chat-thread-top {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  z-index: 50 !important;
  width: auto !important;
  box-shadow: none !important; 
}

.chat-thread-pill {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  width: auto !important;
  max-width: none !important;
  margin: 0 !important;
  border-radius: 0 !important; 
  border: none !important;

  background-color: #000000 !important; 
  background-image: url("https://pic.imgdd.cc/i/034laoL5uiorX7TI9tFQiS.png") !important;
  background-size: cover !important; 
  background-position: center -10px !important; 
  background-repeat: no-repeat !important;
  box-shadow: none !important; 

  padding: calc(env(safe-area-inset-top, 20px) + 16px) 16px 20px 16px !important; 
  height: auto !important; 
  box-sizing: border-box !important;
  overflow: hidden !important;
  display: block !important;
  z-index: 50 !important;
}

.chat-thread-center {
  position: absolute !important;
  left: 50% !important;
  top: 0 !important;
  bottom: 0 !important;
  transform: translateX(-50%) translateY(22px) !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  pointer-events: none !important;
  white-space: nowrap !important;
  z-index: 5 !important;
}

.chat-thread-center h2 {
  color: var(--dress-header-title-color); font-family: 'Cinzel', serif !important;
  font-size: var(--dress-header-title-size) !important; font-weight: var(--dress-header-title-weight) !important; 
  margin: 0 !important; text-shadow: 0 1px 4px rgba(0,0,0,0.8) !important;
  text-align: center !important;
  transform: translateY(4px) !important;
}
.chat-thread-status, .chat-thread-subtitle, .chat-thread-center > div:not(h2) {
  display: block !important; visibility: visible !important; opacity: 1 !important;
  color: #ffffff !important; text-shadow: 0 1px 3px rgba(0,0,0,0.9) !important;
  font-size: 11px !important; margin-top: 4px !important;
  text-align: center !important;
}

.chat-thread .chat-back {
  position: absolute !important;
  left: 16px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 32px !important;
  height: 32px !important;
  margin: 0 !important;
  padding: 0 !important;
  display: block !important;
  color: transparent !important; 
  z-index: 10 !important;
  box-sizing: border-box !important;
}
.chat-thread .chat-back * { opacity: 0 !important; }
.chat-thread .chat-back::after {
  content: '➻'; position: absolute; top: 108%; left: 50%;
  transform: translate(-50%, -50%) scaleX(-1); font-size: 22px; color: #ffffff; text-shadow: 0 1px 4px rgba(0,0,0,0.8);
}

.chat-thread-pill::after {
  content: "" !important; position: absolute !important; bottom: 0 !important; left: 0 !important;
  width: 200% !important; height: 14px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="0.8"/></svg>') !important;
  background-size: 120px 14px !important; background-repeat: repeat-x !important;
  animation: header-ecg 3s linear infinite !important; opacity: 0.8 !important; z-index: 1 !important;
}
.chat-thread-pill::before {
  content: '❤' !important; position: absolute !important; bottom: 2px !important; left: 50% !important;
  transform: translateX(-50%) !important; font-size: 14px !important; color: #ffffff !important; 
  text-shadow: 0 0 5px rgba(255, 255, 255, 0.8) !important;
  animation: heart-beat-center 1.5s ease-in-out infinite alternate !important; z-index: 2 !important;
}
@keyframes header-ecg { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes heart-beat-center {
  0% { transform: translateX(-50%) translateY(0) scale(1); }
  50% { transform: translateX(-50%) translateY(-4px) scale(1.2); }
  100% { transform: translateX(-50%) translateY(0) scale(1); }
}

/* ========== D. 头像与气泡 ========== */
.chat-msg {
  display: flex !important;
  align-items: center !important; 
}

.chat-msg.is-them .chat-msg-body { transform: translateX(-10px) translateY(10px) !important; }
.chat-msg.is-me .chat-msg-body { transform: translateX(10px) translateY(10px) !important; }

.chat-ava {
  width: 38px !important; height: 38px !important; border-radius: 0 !important; 
  position: relative !important; overflow: visible !important; box-sizing: border-box !important;
  flex-shrink: 0 !important;
}

.chat-msg.is-them .chat-ava {
  border: 2px solid #ffffff !important; 
  box-shadow: inset 0 0 0 1px #000000 !important; 
  background: #000 !important; 
  transform: translateX(-8px) !important; 
}
.chat-msg.is-me .chat-ava {
  border: 2px solid #000000 !important; 
  box-shadow: inset 0 0 0 1px #ffffff !important; 
  background: #fff !important; 
  transform: translateX(8px) !important; 
}



.chat-msg.is-them .chat-ava::after {
  content: '⊹'; position: absolute; bottom: -8px; right: -6px; font-size: 16px; color: #fff; 
  text-shadow: 0 0 2px #000, 1px 1px 0 #000, -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000; z-index: 10;
}
.chat-msg.is-me .chat-ava::after {
  content: '⊹'; position: absolute; bottom: -8px; left: -6px; font-size: 16px; color: #000; 
  text-shadow: 0 0 2px #fff, 1px 1px 0 #fff, -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff; z-index: 10;
}

.chat-ava img {
  position: relative !important; 
  overflow: hidden !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  padding: 1px !important;
  box-sizing: border-box !important;
}
.chat-ava img::after {
  content: ""; position: absolute; top: 0; left: -150%; width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);
  transform: skewX(-20deg); animation: avatar-flow 3s infinite;
}
@keyframes avatar-flow { 0% { left: -150%; } 50% { left: 150%; } 100% { left: 150%; } }

.chat-msg-name {
  font-family: 'Cinzel', serif !important; font-weight: 300 !important; font-size: 11px !important; 
  opacity: 1 !important; color: #888 !important; margin-bottom: 2px !important;
}
.chat-msg.is-me .chat-msg-name { display: none !important; }

.chat-msg-time-divider, .chat-thread-time, .chat-thread-notice, .chat-time-divider {
  display: block !important; width: 100% !important; text-align: center !important;
  margin: 12px 0 !important; padding: 0 !important; color: #888 !important; font-size: 10px !important;
  position: relative !important; transform: none !important;
}
.chat-msg-time, .chat-msg-timestamp {
  display: block !important; width: auto !important; position: static !important;
  margin-top: 6px !important; padding: 0 !important; color: #888 !important; font-size: 10px !important; transform: none !important;
}
.chat-msg.is-them .chat-msg-time, .chat-msg.is-them .chat-msg-timestamp { text-align: left !important; }
.chat-msg.is-me .chat-msg-time, .chat-msg.is-me .chat-msg-timestamp { text-align: right !important; }

/* ========== E. 气泡 ========== */
.chat-bubble { 
  line-height: 1.5 !important; 
  position: relative !important; 
  font-family: 'Songti SC', 'STSong', 'SimSun', serif !important;
  font-weight: 300 !important; letter-spacing: 1px;

  min-height: 38px !important;
  display: flex !important;
  flex-direction: column !important; 
  justify-content: center !important;
  box-sizing: border-box !important;
}

.chat-msg.is-them .chat-bubble { padding: 6px 26px 6px 12px !important; }
.chat-msg.is-me .chat-bubble { padding: 6px 12px 6px 26px !important; }

.chat-msg.is-them .chat-bubble::after {
  content: '۩' !important; position: absolute !important; right: 6px !important; bottom: 4px !important; 
  font-size: 22px !important; line-height: 1 !important; color: #ffffff !important; 
  text-shadow: 0 1px 3px rgba(0,0,0,0.8) !important; z-index: 1 !important; pointer-events: none !important;
}
.chat-msg.is-me .chat-bubble::before {
  content: '✟' !important; position: absolute !important; left: 6px !important; bottom: 4px !important; 
  font-size: 22px !important; line-height: 1 !important; color: #000000 !important; 
  text-shadow: none !important; z-index: 1 !important; pointer-events: none !important;
}
.chat-msg.is-them .chat-msg-body::before,
.chat-msg.is-me .chat-msg-body::before { display: none !important; content: none !important; }

.chat-msg-body::after {
  content: "" !important; position: absolute !important; top: -25px; left: -25px; right: -25px; bottom: -25px; pointer-events: none !important;
  background-image: 
    radial-gradient(circle, rgba(255,255,255,1) 2px, transparent 2px),
    radial-gradient(circle, rgba(255,255,255,0.7) 1.5px, transparent 1.5px),
    radial-gradient(circle, rgba(255,255,255,0.5) 2.5px, transparent 2.5px) !important;
  background-size: 50px 50px, 70px 70px, 90px 90px !important;
  background-position: 0 0, 25px 35px, 50px 15px !important;
  animation: stars-irregular 3s ease-in-out infinite alternate !important; z-index: 0 !important; 
}
@keyframes stars-irregular {
  0% { opacity: 0.1; transform: scale(0.95); }
  30% { opacity: 0.9; transform: scale(1.05); }
  60% { opacity: 0.2; transform: scale(0.98); }
  100% { opacity: 0.7; transform: scale(1.02); }
}

/* ========== 红包 & 礼物 ========== */
.chat-msg[class*="red"] .chat-bubble, 
.chat-msg[class*="gift"] .chat-bubble,
.chat-bubble[class*="transfer"], .chat-bubble[class*="gift"], .chat-bubble[class*="red-packet"],
.chat-bubble[class*="red-envelope"], .puff-transfer, .puff-gift, .puff-red-packet {
  background: linear-gradient(135deg, #2a2a2a 0%, #000000 100%) !important; 
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-radius: 0 !important; box-shadow: 0 4px 15px rgba(0,0,0,0.8) !important; 
  position: relative !important; 
}
.chat-msg[class*="red"] .chat-bubble *, 
.chat-msg[class*="gift"] .chat-bubble *,
.chat-bubble[class*="transfer"] *, .chat-bubble[class*="gift"] *, .chat-bubble[class*="red-packet"] *,
.chat-bubble[class*="red-envelope"] *, .puff-transfer *, .puff-gift *, .puff-red-packet * {
  border: none !important; border-radius: 0 !important; background: transparent !important; 
  box-shadow: none !important; color: #ffffff !important; 
}

/* ========== L. 底栏 ========== */
.chat-thread .chat-compose {
  background-color: #000000 !important;
  background-image: url("https://pic.imgdd.cc/i/034suYLImDhb0GDTq9Sfoo.png") !important;
  background-size: cover !important; 
  background-position: center bottom !important; 
  background-repeat: no-repeat !important;
  border-top: none !important; 
  padding: 20px 16px calc(env(safe-area-inset-bottom, 20px) + 8px) 16px !important;
  box-shadow: none !important;
  z-index: 50 !important; 
  position: relative !important;
}

.chat-thread .chat-compose-bar {
  background: transparent !important; 
  border: none !important; 
  box-shadow: none !important; 
  position: relative !important; 
  width: 100% !important; 
  padding: 0 !important; 
  margin: 0 !important;
  min-height: 36px !important; 
  display: block !important; 
}

.chat-thread .chat-compose-input {
  border: 1.5px solid transparent !important; 
  border-radius: 0 !important; 
  margin: 0 !important; 
  margin-left: 35px !important; 
  margin-right: 85px !important; 
  width: calc(100% - 120px) !important;
  padding: 2px 10px 4px 10px !important; 
  height: auto !important; 
  min-height: 36px !important; 
  max-height: 105px !important; 
  overflow-y: auto !important; 
  line-height: 1.5 !important; 
  box-sizing: border-box !important; 

  color: #ffffff !important; font-family: 'Cinzel', serif !important; font-size: 14px !important;
  box-shadow: none !important; 
  backdrop-filter: none !important; 
  -webkit-backdrop-filter: none !important;
  transform: none !important; 
  text-shadow: 0 1px 3px rgba(0,0,0,0.8) !important; 

  background: transparent !important; 
  transition: background 0.2s, backdrop-filter 0.2s, border-color 0.2s, box-shadow 0.2s !important;
}

.chat-thread .chat-compose-input:not(:placeholder-shown) {
  background: rgba(0, 0, 0, 0.6) !important; 
  backdrop-filter: blur(4px) !important; 
  -webkit-backdrop-filter: blur(4px) !important;
  border: 1.5px solid #000000 !important; 
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.4) !important;
}

.chat-thread .chat-compose-plus,
.chat-thread .chat-compose-bar > :first-child:not(.chat-compose-input) {
  position: absolute !important;
  left: 0 !important;
  bottom: 2px !important; 
  width: 32px !important;
  height: 32px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: transparent !important;
  font-size: 0 !important;
  line-height: 0 !important;
  overflow: visible !important;
}

/* 【修复】去除了冲突的代码，并将 translateY 改为 -3px 实现上移 */
.chat-thread .chat-compose-plus::after,
.chat-thread .chat-compose-bar > :first-child:not(.chat-compose-input)::after {
  content: '✙' !important;
  transform: translateY(-3px) !important; 
  position: absolute !important;
  inset: 0 !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  font-size: 24px !important;
  line-height: 1 !important;
  font-family: system-ui, -apple-system, sans-serif !important;
  color: #ffffff !important;
  text-shadow: 0 1px 4px rgba(0,0,0,0.8) !important;
  pointer-events: none !important;
}

.chat-thread .chat-compose-bar > .chat-compose-action { display: none !important; }

.chat-thread div.chat-compose-popover,
.chat-thread .compose-popover,
.chat-thread [class*="compose-popover"],
.chat-thread .chat-compose-extend {
  background: linear-gradient(135deg, #1c1c1c 0%, #000000 100%) !important;
  border: 1px solid #333 !important;
  border-radius: 0 !important; 
  box-shadow: 0 4px 20px rgba(0,0,0,0.8) !important;
  color: #ccc !important;
}

.chat-thread div.chat-compose-popover *,
.chat-thread .compose-popover *,
.chat-thread [class*="compose-popover"] *,
.chat-thread .chat-compose-extend * {
  color: #ccc !important;
}

.chat-thread div.chat-compose-popover svg,
.chat-thread .compose-popover svg,
.chat-thread [class*="compose-popover"] svg {
  fill: #ccc !important;
}

.chat-thread div.chat-compose-popover button,
.chat-thread div.chat-compose-popover .chat-compose-action,
.chat-thread div.chat-compose-popover [class*="action"],
.chat-thread [class*="compose-popover"] button,
.chat-thread [class*="compose-popover"] [class*="action"] {
  background: transparent !important;
  border: 1px solid #333 !important;
  border-radius: 0 !important;
  color: #fff !important;
}

/* ========== 声音与发送 ========== */
.chat-thread .chat-compose-icon.is-voice, .chat-thread .chat-compose-icon.is-send,
.chat-thread .chat-compose-icon.is-send.ready, .chat-thread .chat-compose-icon.is-reply {
  background: transparent !important; 
  border: none !important; 
  box-shadow: none !important;
  width: 32px !important; 
  height: 32px !important; 
  color: transparent !important;
  transform: none !important; 
  position: absolute !important; 
}

.chat-thread .chat-compose-icon.is-voice {
  right: 44px !important;
  bottom: 2px !important; 
  background: transparent url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-size="24" fill="%23ffffff">♪</text></svg>') center / 22px 22px no-repeat !important;
}
.chat-thread .chat-compose-icon.is-voice * { display: none !important; }

.chat-thread .chat-compose-icon.is-send,
.chat-thread .chat-compose-icon.is-reply {
  right: 0 !important;
  bottom: 2px !important; 
  background: transparent url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" font-size="26" fill="%23ffffff">☯</text></svg>') center / 24px 24px no-repeat !important;
  animation: taiji-spin 4s linear infinite !important;
}
@keyframes taiji-spin { 
  0% { transform: rotate(0deg); } 
  100% { transform: rotate(360deg); } 
}

/* ========== 引用消息 ========== */
.chat-thread .chat-qq-quote {
  background: transparent !important; 
  border: none !important; 
  /* 【修改】左侧竖线改细为 1px */
  border-left: 1px solid #000000 !important; 
  position: relative !important; 
  padding: 6px 8px 14px 8px !important; 
  margin-bottom: 6px !important; 
  overflow: hidden !important;
  display: block !important; 
  width: 100% !important; 
}
.chat-thread .chat-qq-quote::after {
  content: "" !important; position: absolute !important; bottom: 0 !important; left: 0 !important; width: 200% !important; height: 12px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23000000" stroke-width="0.8"/></svg>') !important;
  background-size: 100px 12px !important; background-repeat: repeat-x !important; animation: ecg-flow 3s linear infinite !important; opacity: 1 !important; z-index: 0 !important;
}
@keyframes ecg-flow { 0% { background-position: 0 0; } 100% { background-position: -100px 0; } }
.chat-thread .chat-qq-quote-name, .chat-thread .chat-qq-quote-text, .chat-thread .chat-qq-quote-text * {
  color: #000000 !important; font-size: 12px !important; line-height: 1.4 !important; 
  position: relative !important; z-index: 1 !important; text-shadow: none !important; 
  opacity: 1 !important;
}
.chat-thread .chat-qq-quote-name { font-weight: bold !important; margin-bottom: 2px !important; }

/* ========== 长按菜单弹窗（纯黑、方角、白字、白图标） ========== */
.chat-thread [class*="menu"], 
.chat-thread [class*="action-sheet"], 
.chat-thread [class*="popover"],
.chat-thread [class*="context-menu"],
.chat-thread .puff-menu {
  background-color: #000000 !important;
  border: 1px solid #333333 !important; 
  color: #ffffff !important;
  box-shadow: 0 4px 20px rgba(0,0,0,0.9) !important;
  border-radius: 0 !important; 
}

.chat-thread [class*="menu"] *, 
.chat-thread [class*="action-sheet"] *, 
.chat-thread [class*="popover"] *,
.chat-thread [class*="context-menu"] *,
.chat-thread .puff-menu * {
  color: #ffffff !important;
  border-radius: 0 !important; 
}

/* 图标背景：透明，方角，带极细边框 */
.chat-thread [class*="menu"] [class*="icon"],
.chat-thread [class*="menu"] [class*="circle"],
.chat-thread [class*="action"] [class*="icon"],
.chat-thread [class*="action"] [class*="circle"],
.chat-thread [class*="popover"] [class*="icon-bg"] {
  background-color: transparent !important; /* 中间不要黑色 */
  border-radius: 0 !important;              /* 方角框 */
  border: 1px solid rgba(255, 255, 255, 0.2) !important; /* 淡淡的边框，显形 */
}

/* 图标强制变白 */
.chat-thread [class*="menu"] svg,
.chat-thread [class*="action-sheet"] svg,
.chat-thread [class*="popover"] svg,
.chat-thread [class*="context-menu"] svg {
  fill: #ffffff !important;
  stroke: #ffffff !important;
  filter: brightness(0) invert(1) !important; /* 如果原生是黑色图片，强制反白 */
}

.chat-thread [class*="menu"] [class*="preview"],
.chat-thread [class*="menu"] [class*="content"] {
  background-color: #111111 !important;
  color: #ffffff !important;
}

/* 删除按钮保持红色 */
.chat-thread [class*="menu"] [class*="delete"],
.chat-thread [class*="action"] [class*="delete"] {
  color: #ff5555 !important;
}
.chat-thread [class*="menu"] [class*="delete"] svg {
  fill: #ff5555 !important;
  stroke: #ff5555 !important;
